#!/bin/bash -el
# Authors: Seth McGinnis, Jacob Stuivenvolt-Allen
#
# clean_index.sh - Apply corrected CF metadata to a single climate index
# output file (in place).
#
# Part of the postprocessing index-generation workflow.  Called by
# commandfiles generated by index.py (cleanup.cmd), on the files index.py's
# indices/derived steps wrote directly to OUTDIR.
#
# Reads index specs from gis_indexes.tsv (in SETUPDIR).  FILE is expected to
# contain exactly one data variable (whatever name CDO left it under); it
# gets renamed to the TSV's 'index' value and given corrected attributes.
# If the index has a threshold, a scalar threshold coordinate variable is
# added.
#
# Usage: clean_index.sh INDEX FILE SETUPDIR
#
#   INDEX    Index name (row key into gis_indexes.tsv, e.g. CDD, CDDn)
#   FILE     Raw index file to clean up in place
#   SETUPDIR Directory containing gis_indexes.tsv

set -eo pipefail

module load nco
module load cdo

padding="10000"  # 10 KB header padding reduces odds of file rewrites later

# ---------------------------------------------------------------------------
# Arguments
# ---------------------------------------------------------------------------

[[ $# -ne 3 ]] && {
    echo "Usage: $(basename "$0") INDEX FILE SETUPDIR" >&2
    exit 1
}

index="$1"
outfile="$2"
setupdir="$3"

# ---------------------------------------------------------------------------
# Load index spec from SETUPDIR
# ---------------------------------------------------------------------------

indexes_tsv="$setupdir/gis_indexes.tsv"

[[ ! -f "$indexes_tsv" ]] && {
    echo "Error: gis_indexes.tsv not found: $indexes_tsv" >&2
    exit 1
}

# ---------------------------------------------------------------------------
# Look up the row for INDEX in gis_indexes.tsv
# ---------------------------------------------------------------------------
# Columns are located by header name, not position, since the TSV may have
# extra columns (e.g., preset columns left of 'index').

declare -A col
while IFS=$'\t' read -r name num; do
    col[$name]=$num
done < <(awk -F'\t' 'NR==1 {for (i=1; i<=NF; i++) if ($i != "") print $i "\t" i; exit}' \
             "$indexes_tsv")

for c in index threshold th_units out_units long_name description \
         standard_name cell_methods units_metadata; do
    if [[ -z "${col[$c]}" ]]; then
        echo "Error: column '$c' missing from header of $indexes_tsv" >&2
        exit 1
    fi
done

row="$(awk -F'\t' -v i="$index" -v c="${col[index]}" \
           'NR>1 && $c==i {print; exit}' "$indexes_tsv")"

[[ -z "$row" ]] && {
    echo "Error: Index '$index' not found in gis_indexes.tsv" >&2
    exit 1
}

field() { echo "$row" | cut -f"${col[$1]}"; }

threshold=$(     field threshold)
th_units=$(      field th_units)
out_units=$(     field out_units)
long_name=$(     field long_name)
description=$(   field description)
standard_name=$( field standard_name)
cell_methods=$(  field cell_methods)
units_metadata=$(field units_metadata)

# ---------------------------------------------------------------------------
# Discover the file's data variable name (expected: exactly one).
# ---------------------------------------------------------------------------

raw_var="$(cdo showname "$outfile" 2>/dev/null | xargs)"

[[ -z "$raw_var" ]] && {
    echo "Error: could not determine data variable name in $outfile" >&2
    exit 1
}
[[ "$raw_var" == *" "* ]] && {
    echo "Error: expected exactly one data variable in $outfile, got: $raw_var" >&2
    exit 1
}

# get attribute from the raw variable, before renaming
get_attr() {
    local attr="$1"
    ncdump -h "$outfile" \
        | awk -v v="$raw_var" -v a="$attr" \
              '$0 ~ "^\t\t"v":"a" " {
                  sub(/^[^"]*"/, ""); sub(/".*/, ""); print; exit
              }'
}

input_units=$(get_attr "units") || true

# Output units: carry through input's units unless out_units overrides it.
units="${out_units:-$input_units}"

# ---------------------------------------------------------------------------
# Step 1: Rewrite header in place, padded, since we may add a scalar
# threshold coordinate later.
# ---------------------------------------------------------------------------

ncks -h -O -7 --hdr_pad $padding "$outfile" "$outfile"

# ---------------------------------------------------------------------------
# Step 2: Delete stale tracking_id global attribute
# ---------------------------------------------------------------------------

ncatted -h -a tracking_id,global,d,, "$outfile"

# ---------------------------------------------------------------------------
# Step 3: Add threshold scalar coordinate(s), if applicable.
# ---------------------------------------------------------------------------

## TODO: get stdname of input_var and set as stdname of threshold/range
## (but currently, some of them don't have a stdname)

if [[ -n "$threshold" ]]; then
    if [[ "$threshold" == *,* ]]; then
       # if there's a comma, it's actually a range
       IFS=, read -r rmin rmax <<< "${threshold}"
       ncap2 -h -A -s "rmin=double(${rmin});rmax=double(${rmax})" "$outfile"
       ncatted -h -a units,'^(rmin|rmax)$',o,c,"${th_units}" "$outfile"
       ncatted -h -a coordinates,"${raw_var}",a,c," rmin rmax" "$outfile"
    else
      ncap2 -h -A -s "threshold=double(${threshold})" "$outfile"
      ncatted -h -a units,threshold,o,c,"${th_units}" "$outfile"
      ncatted -h -a coordinates,"${raw_var}",a,c," threshold" "$outfile"
    fi
fi

# ---------------------------------------------------------------------------
# Step 4: Rename variable and write corrected attributes.
# ---------------------------------------------------------------------------

if [[ "$raw_var" != "$index" ]]; then
    ncrename -h -v "${raw_var},${index}" "$outfile"
fi

ncatted -h -a units,"${index}",o,c,"${units}" "$outfile"

[[ -n "$standard_name" ]] && \
    ncatted -h -a standard_name,"${index}",o,c,"${standard_name}" "$outfile"

[[ -n "$long_name" ]] && \
    ncatted -h -a long_name,"${index}",o,c,"${long_name}" "$outfile"

[[ -n "$description" ]] && \
    ncatted -h -a comment,"${index}",o,c,"${description}" "$outfile"

[[ -n "$cell_methods" && "$cell_methods" != \[TODO:* ]] && \
    ncatted -h -a cell_methods,"${index}",o,c,"${cell_methods}" "$outfile"

[[ -n "$units_metadata" ]] && \
    ncatted -h -a units_metadata,"${index}",o,c,"${units_metadata}" "$outfile"

echo "Done"
exit 0
